import sys
sys.setrecursionlimit(200005)
def solve(n, m, edges):
    edges.sort(key=lambda x: x[2])
    parent = list(range(n))

    def find(i):
        if parent[i] == i: return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i, root_j = find(i), find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    mst_weight = 0
    mst_edges = []
    used_edges = [False] * m

    for i in range(m):
        u, v, w = edges[i]
        u -= 1; v -= 1
        if union(u, v):
            mst_weight += w
            mst_edges.append((u, v, w))
            used_edges[i] = True

    if len(mst_edges) != n - 1: return "-1"

    adj = [[] for _ in range(n)]
    for u, v, w in mst_edges:
        adj[u].append((v, w)); adj[v].append((u, w))

    LOG = 18
    up = [[-1] * LOG for _ in range(n)]
    max_w = [[-1] * LOG for _ in range(n)]
    depth = [0] * n

    def dfs(node, p, d, w_p):
        depth[node] = d
        up[node][0] = p
        max_w[node][0] = w_p

        for i in range(1, LOG):
            if up[node][i-1] != -1:
                up[node][i] = up[up[node][i-1]][i-1]
                max_w[node][i] = max(max_w[node][i-1], max_w[up[node][i-1]][i-1])
            else:
                up[node][i] = -1; max_w[node][i] = -1

        for neighbor, weight in adj[node]:
            if neighbor != p: dfs(neighbor, node, d + 1, weight)

    dfs(0, -1, 0, -1)

    def get_max_edge(u, v):
        res = -1
        if depth[u] < depth[v]: u, v = v, u

        diff = depth[u] - depth[v]
        for i in range(LOG):
            if (diff >> i) & 1:
                res = max(res, max_w[u][i])
                u = up[u][i]

        if u == v: return res

        for i in range(LOG - 1, -1, -1):
            if up[u][i] != up[v][i]:
                res = max(res, max_w[u][i])
                res = max(res, max_w[v][i])
                u = up[u][i]; v = up[v][i]

        res = max(res, max_w[u][0])
        res = max(res, max_w[v][0])
        return res

    ans = float('inf')
    for i in range(m):
        if not used_edges[i]:
            u, v, w = edges[i]
            u -= 1; v -= 1
            max_e = get_max_edge(u, v)
            if max_e != -1:
                ans = min(ans, mst_weight - max_e + w)

    if ans == float('inf'): return "-1"
    return str(ans)

if __name__ == '__main__':
    input_data = sys.stdin.read().split()
    if not input_data: exit()
    n, m = int(input_data[0]), int(input_data[1])
    edges = []
    idx = 2
    for _ in range(m):
        edges.append([int(input_data[idx]), int(input_data[idx+1]), int(input_data[idx+2])])
        idx += 3
    print(solve(n, m, edges))

